def main():
    input_data = sys.stdin.read().split()
    if len(input_data) < 2:
        return

    n = int(input_data[0])
    s = input_data[1]

    m = len(s)
    # Use integers directly for simpler logic
    vals = [1 if ch == '1' else 0 for ch in s]
    costs = [1] * m

    # Process from the leaves up to the root
    for _ in range(n):
        m //= 3
        # Update in-place to save memory and allocation overhead
        for i in range(m):
            j = i * 3
            a = vals[j]
            b = vals[j+1]
            c = vals[j+2]

            ca = costs[j]
            cb = costs[j+1]
            cc = costs[j+2]

            s_val = a + b + c

            # Majority is 1
            if s_val >= 2:
                vals[i] = 1
                if s_val == 2:
                    # To flip to 0, we flip one of the 1s (which has the minimum cost)
                    if a == 0:
                        costs[i] = cb if cb < cc else cc
                    elif b == 0:
                        costs[i] = ca if ca < cc else cc
                    else:
                        costs[i] = ca if ca < cb else cb
                else:
                    # All three are 1; to flip to 0, we need to flip two 1s (sum of two smallest costs)
                    mx = ca if ca > cb else cb
                    mx = mx if mx > cc else cc
                    costs[i] = ca + cb + cc - mx

            # Majority is 0
            else:
                vals[i] = 0
                if s_val == 1:
                    # To flip to 1, we flip one of the 0s (which has the minimum cost)
                    if a == 1:
                        costs[i] = cb if cb < cc else cc
                    elif b == 1:
                        costs[i] = ca if ca < cc else cc
                    else:
                        costs[i] = ca if ca < cb else cb
                else:
                    # All three are 0; to flip to 1, we need to flip two 0s (sum of two smallest costs)
                    mx = ca if ca > cb else cb
                    mx = mx if mx > cc else cc
                    costs[i] = ca + cb + cc - mx

    print(costs[0])

